import type { Segment, Vec3 } from '../lang/interp';

/** Stan rysunku współdzielony między interpreterem a widokami. */
export interface Draw {
  segments: Segment[];
  version: number;
  pos: Vec3;
  h: Vec3;
  r: Vec3;
  u: Vec3;
  pen: boolean;
  /** Wzór zadania (półprzezroczysty). */
