      ctx.stroke();
      const axes: Array<[Vec3, string, string]> = [[[ext, 0, 0], 'X', '#c0392b'], [[0, ext, 0], 'Y', '#2f8f4e'], [[0, 0, ext], 'Z', '#2b6fb3']];
