    const first = this.w === 300 && this.hgt === 300;
    this.w = r.width; this.hgt = r.height;
    this.dpr = window.devicePixelRatio || 1;
    this.canvas.width = Math.round(this.w * this.dpr);
    this.canvas.height = Math.round(this.hgt * this.dpr);
