import type { Segment } from '../lang/interp';
import { h } from './dom';
import { cssVar, Draw, View } from './draw';

/** Sprawdza, czy przeglądarka potrafi utworzyć kontekst WebGL; zwraca powód niepowodzenia albo null. */
