  private w = 300;
  private hgt = 300;
  private waiters: Array<() => void> = [];
  private canvas: HTMLCanvasElement;

  constructor(private draw: Draw) {
    this.renderer = new WebGLRenderer({ antialias: true, alpha: false, preserveDrawingBuffer: true });
