import { COMMAND_DOCS, SECTIONS, SHORTCUTS } from '../data/reference';
import { EXAMPLES } from '../data/examples';
import { permalinkHash } from '../lib/share';
import type { Mode } from '../lang/parser';
import { h } from './dom';
import { highlight } from './highlight';

function code(src: string): HTMLElement {
  const pre = h('pre', { class: 'code', tabindex: 0, 'aria-label': 'Przykładowy kod' });
  const c = h('code', {});
  c.innerHTML = highlight(src).replace(/\n$/, '');
  pre.append(c);
  return pre;
}

function tryLink(src: string, mode: Mode): HTMLElement {
  return h('a', { class: 'btn btn-small', href: permalinkHash(src, mode) }, `Wypróbuj w pracowni (${mode.toUpperCase()})`);
}

function example(src: string, mode: Mode, caption?: string): HTMLElement {
  return h('figure', { class: 'ex' },
    caption ? h('figcaption', {}, caption) : null,
    code(src),
    h('div', { class: 'ex-actions' }, tryLink(src, mode)));
}

export function renderReference(): HTMLElement {
  const root = h('div', { class: 'doc' });
  const toc = h('nav', { class: 'toc', 'aria-label': 'Spis treści' });
  const tocList = h('ul', {});
  toc.append(h('h2', {}, 'Spis treści'), tocList);
  const addToc = (id: string, title: string) => {
    tocList.append(h('li', {}, h('a', {
      href: '#/instrukcja', onclick: (e: Event) => {
        e.preventDefault();
        const t = document.getElementById(id);
        t?.scrollIntoView({ behavior: 'auto', block: 'start' });
        t?.focus({ preventScroll: true });
      },
    }, title)));
  };

  const main = h('div', { class: 'doc-main' });
  main.append(h('h1', { id: 'ref-title', tabindex: -1 }, 'Instrukcja języka Logo'),
    h('p', { class: 'lead' }, 'Wszystko, co potrafi Logomocja: polecenia, wyrażenia, zmienne, warunki, procedury i limity. Każdy przykład możesz otworzyć w pracowni jednym kliknięciem.'));

  const addSection = (id: string, title: string, body: Array<Node | string>) => {
    addToc(id, title);
    main.append(h('section', { class: 'doc-sec', 'aria-labelledby': `h-${id}` },
      h('h2', { id, tabindex: -1 }, h('span', { id: `h-${id}` }, title)), ...body));
  };

  for (const s of SECTIONS.slice(0, 3)) {
    const body = h('div', { class: 'prose' });
    body.innerHTML = s.html;
    addSection('s-' + s.id, s.title, [body, ...(s.examples ?? []).map(e => example(e.code, e.mode, e.caption))]);
  }

  // polecenia
  const cmds = h('div', { class: 'cmds' });
  for (const d of COMMAND_DOCS) {
    cmds.append(h('article', { class: 'cmd', id: `cmd-${d.id}` },
      h('h3', {}, h('code', {}, d.syntax), d.mode === '3d' ? h('span', { class: 'badge' }, '3D') : null),
      h('p', { class: 'aliases' }, 'Polskie: ', h('code', {}, d.polish.join(', ')), ' · angielskie: ', h('code', {}, d.english.join(', '))),
      h('p', {}, d.summary),
      example(d.example, d.mode)));
  }
  addSection('s-polecenia', 'Polecenia', [
    h('p', {}, 'Każde polecenie ma polskie i angielskie nazwy; wszystkie są równoważne. Polecenia „gora”, „dol”, „pp” i „pl” działają tylko w trybie 3D.'),
    cmds,
  ]);

  for (const s of SECTIONS.slice(3)) {
    const body = h('div', { class: 'prose' });
    body.innerHTML = s.html;
    addSection('s-' + s.id, s.title, [body, ...(s.examples ?? []).map(e => example(e.code, e.mode, e.caption))]);
  }

  // gotowe programy
  addSection('s-programy', 'Gotowe programy', [
    h('p', {}, 'Przykłady z pracowni (przycisk „Przykłady”):'),
    h('ul', { class: 'plain' }, ...EXAMPLES.map(e => h('li', {}, h('a', { href: permalinkHash(e.source, e.mode) }, e.name), ` (${e.mode.toUpperCase()}): ${e.blurb}`))),
  ]);

  addSection('s-skroty', 'Skróty klawiszowe', [
    h('table', { class: 'keys' },
      h('thead', {}, h('tr', {}, h('th', { scope: 'col' }, 'Skrót'), h('th', { scope: 'col' }, 'Działanie'))),
      h('tbody', {}, ...SHORTCUTS.map(s => h('tr', {}, h('td', {}, h('kbd', {}, s.keys)), h('td', {}, s.action))))),
  ]);

  root.append(toc, main);
  return root;
}
EOF
cat > src/main.ts <<'EOF'
import './style.css';
import { run } from './lang/interp';
import type { Mode } from './lang/parser';
import { parseHash } from './lib/share';
import * as store from './lib/storage';
import { h } from './ui/dom';
import { renderReference } from './ui/reference';
import { Studio } from './ui/studio';

const VERSION = '1.0.0';

type Theme = 'auto' | 'light' | 'dark';
const THEME_LABEL: Record<Theme, string> = { auto: 'Motyw: systemowy', light: 'Motyw: jasny', dark: 'Motyw: ciemny' };
const THEME_ICON: Record<Theme, string> = { auto: '◐', light: '☀', dark: '☾' };

let studio!: Studio;
let resolveReady: () => void;
const ready = new Promise<void>(r => { resolveReady = r; });

async function goStudio() {
  const target = '#/';
  if (parseHash(location.hash).path !== '/') {
    location.hash = target;
    await new Promise(r => setTimeout(r, 0));
  }
  await ready;
}

declare global {
  interface Window {
    logomocja: {
      version: string;
      run: typeof run;
      open: (source: string, mode: Mode) => ReturnType<Studio['open']>;
    };
  }
}

window.logomocja = {
  version: VERSION,
  run: (source, mode) => run(source, mode),
  open: async (source, mode) => {
    await goStudio();
    return studio.open(source, mode);
  },
};

function applyTheme(t: Theme) {
  const root = document.documentElement;
  if (t === 'auto') root.removeAttribute('data-theme'); else root.dataset.theme = t;
}

function boot() {
  const app = document.getElementById('app')!;
  let theme = (store.load('theme') as Theme) || 'auto';
  if (!['auto', 'light', 'dark'].includes(theme)) theme = 'auto';
  applyTheme(theme);

  const themeBtn = h('button', { type: 'button', class: 'btn btn-ghost' });
  const paintThemeBtn = () => {
    themeBtn.replaceChildren(h('span', { class: 'ico', 'aria-hidden': 'true' }, THEME_ICON[theme]), h('span', { class: 'lbl' }, THEME_LABEL[theme]));
    themeBtn.title = 'Przełącz motyw: systemowy, jasny, ciemny';
  };
  paintThemeBtn();
  themeBtn.addEventListener('click', () => {
    theme = theme === 'auto' ? 'light' : theme === 'light' ? 'dark' : 'auto';
    store.save('theme', theme);
    applyTheme(theme);
    paintThemeBtn();
    studio.themeChanged();
  });
  matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => studio.themeChanged());

  const navStudio = h('a', { href: '#/', class: 'nav-link' }, 'Pracownia');
  const navRef = h('a', { href: '#/instrukcja', class: 'nav-link' }, 'Instrukcja');
  const brand = h('a', { href: '#/', class: 'brand', 'aria-label': 'Logomocja, strona główna' },
    h('svg', { class: 'brand-ico', viewBox: '0 0 32 32', 'aria-hidden': 'true' }),
    h('span', { class: 'brand-name' }, 'Logomocja'));
  brand.querySelector('svg')!.innerHTML =
    '<path d="M16 3 L25 23 L16 19 L7 23 Z" fill="currentColor" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>';
  const header = h('header', { class: 'topbar' }, brand,
    h('nav', { 'aria-label': 'Główna nawigacja', class: 'nav' }, navStudio, navRef), themeBtn);
  const skip = h('a', { href: '#main', class: 'skip', onclick: (e: Event) => { e.preventDefault(); document.getElementById('main')!.focus(); } }, 'Przejdź do treści');

  const main = h('main', { id: 'main', tabindex: -1 });
  studio = new Studio();
  const ref = renderReference();
  const refWrap = h('div', { class: 'ref-wrap', hidden: true }, ref);
  main.append(studio.root, refWrap);
  app.replaceChildren(skip, header, main);

  let current = '';
  const route = async () => {
    const r = parseHash(location.hash);
    const isRef = r.path === '/instrukcja';
    const which = isRef ? 'ref' : 'studio';
    studio.root.hidden = isRef;
    refWrap.hidden = !isRef;
    studio.setVisible(!isRef);
    navStudio.toggleAttribute('aria-current', !isRef);
    if (!isRef) navStudio.setAttribute('aria-current', 'page'); else navStudio.removeAttribute('aria-current');
    if (isRef) navRef.setAttribute('aria-current', 'page'); else navRef.removeAttribute('aria-current');
    document.title = isRef ? 'Instrukcja · Logomocja' : 'Logomocja: pracownia żółwia 2D i 3D';
    if (which !== current) {
      current = which;
      if (isRef) document.getElementById('ref-title')?.focus({ preventScroll: false });
      else window.scrollTo(0, 0);
    }
    if (!isRef && r.params.has('kod')) await studio.openFromParams(r.params);
  };
  window.addEventListener('hashchange', () => { void route(); });
  void route().then(resolveReady);
}

boot();
EOF
