cd /tmp/debs && cat > /tmp/closure.py <<'EOF'
import lzma, re, subprocess, sys, urllib.request, os
data = lzma.open('/tmp/debs/Packages.xz','rt',encoding='utf-8').read()
pk = {}
prov = {}
for block in data.split('\n\n'):
    d = {}
    for m in re.finditer(r'^([A-Za-z-]+): (.*(?:\n .*)*)', block, re.M):
        d[m.group(1)] = m.group(2)
    if 'Package' in d:
        pk[d['Package']] = d
        for p in d.get('Provides','').split(','):
            p = p.strip().split(' ')[0]
            if p: prov.setdefault(p, d['Package'])
def installed(n):
    return subprocess.run(['dpkg','-s',n],capture_output=True).returncode==0
want = sys.argv[1:]
seen=set(); order=[]
def visit(n):
    if n in seen: return
    if n not in pk:
        n = prov.get(n)
        if n is None or n in seen: return
    seen.add(n)
    if installed(n): return
    order.append(n)
    for dep in pk[n].get('Depends','').split(','):
        dep = dep.split('|')[0].strip().split(' ')[0]
        if dep: visit(dep)
for w in want: visit(w)
os.makedirs('/tmp/debs/pkgs',exist_ok=True)
for n in order:
    fn = pk[n]['Filename']
    out = '/tmp/debs/pkgs/'+os.path.basename(fn)
    if not os.path.exists(out):
        urllib.request.urlretrieve('https://deb.debian.org/debian/'+fn, out)
    subprocess.run(['dpkg','-x',out,'/tmp/debs/root'],check=True)
print(len(order), 'packages')
EOF
