input.command:
sed -i 's/^\* { box-sizing: border-box; }/* { box-sizing: border-box; }\n[hidden] { display: none !important; }/' src/style.css && BASE_PATH=/Logomocja/builds/x/ bun run build 2>&1 | grep -ci error; cat > /tmp/pw/t3.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
const base = 'http://localhost:4173/Logomocja/builds/x/';
const logs = [];
const mk = async (opts = {}) => {
  const ctx = await b.newContext({ viewport: { width: 1280, height: 800 }, ...opts });
  const p = await ctx.newPage();
  p.on('console', m => { if (m.type() === 'error') logs.push(m.type() + ': ' + m.text()); });
  p.on('pageerror', e => logs.push('PAGEERR ' + e.message));
  return p;
};
// permalink
let p = await mk();
const src = 'kolor "#2b6fb3"\npowtorz 6 [np 80 pw 60]';
const enc = Buffer.from(src).toString('base64url');
await p.goto(base + '#/?tryb=2d&kod=' + enc);
await p.waitForTimeout(1200);
console.log('permalink editor:', JSON.stringify(await p.locator('#editor-input').inputValue()));
console.log('url after:', p.url());
await p.screenshot({ path: 'p1.png' });
// 3D + orbit
await p.evaluate(() => window.logomocja.open('powtorz 4 [np 100 pw 90]\ngora 90 np 100 dol 90\npowtorz 4 [np 100 pw 90]', '3d'));
const cv = p.locator('canvas.view-canvas:visible');
const box = await cv.boundingBox();
await p.mouse.move(box.x + 300, box.y + 300);
await p.mouse.down(); await p.mouse.move(box.x + 420, box.y + 250, { steps: 8 }); await p.mouse.up();
await p.waitForTimeout(300);
await p.screenshot({ path: 'p2.png' });
// dark theme
await p.getByRole('button', { name: /Motyw/ }).click();
await p.getByRole('button', { name: /Motyw/ }).click();
console.log('theme attr', await p.evaluate(() => document.documentElement.dataset.theme));
await p.waitForTimeout(300);
await p.screenshot({ path: 'p3.png' });
// reload persists draft
await p.locator('#editor-input').fill('np 77');
await p.reload();
await p.waitForTimeout(500);
console.log('after reload:', JSON.stringify(await p.locator('#editor-input').inputValue()), await p.evaluate(() => document.documentElement.dataset.theme));
// reference page
await p.getByRole('link', { name: 'Instrukcja' }).click();
await p.waitForTimeout(400);
await p.screenshot({ path: 'p4.png' });
console.log('refresh on ref route:');
await p.reload(); await p.waitForTimeout(400);
console.log(await p.locator('h1').first().innerText());
// mobile
const m = await mk({ viewport: { width: 390, height: 780 }, hasTouch: true, isMobile: true });
await m.goto(base);
await m.waitForTimeout(600);
await m.screenshot({ path: 'm1.png' });
await m.getByRole('button', { name: 'Uruchom' }).click();
await m.waitForTimeout(1500);
await m.screenshot({ path: 'm2.png' });
console.log(logs.join('\n'));
await b.close();
EOF
cd /tmp/pw && node t3.mjs 2>&1 | tail -20

